const escapeText = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = new Date().toISOString().slice(0, 10);
const previews = IDEAS.filter(i => i.digestReady && i.sources?.length && i.reviewedAt && i.reviewedAt <= today && Date.parse(today) - Date.parse(i.reviewedAt) <= 30 * 86400000).sort((a, b) => b.reviewedAt.localeCompare(a.reviewedAt)).slice(0, 5);
document.querySelector('#digest-ideas').innerHTML = previews.length ? previews.map(i => `<article class="digest-idea"><div class="meta"><span>${escapeText(i.category)}</span><span>${escapeText(i.model)}</span><span>Reviewed ${escapeText(i.reviewedAt)}</span></div><h3><a href="index.html#${encodeURIComponent(i.id)}">${escapeText(i.title)}</a></h3><p>${escapeText(i.summary)}</p><dl><dt>Evidence</dt><dd>${escapeText(i.evidence)} · ${escapeText(i.status)}</dd><dt>First test</dt><dd>${escapeText(i.pilot[0])}</dd><dt>Main risk</dt><dd>${escapeText(i.risks[0])}</dd></dl><a href="index.html#${encodeURIComponent(i.id)}">Read the full brief →</a></article>`).join('') : '<div class="empty"><h3>The next digest is waiting for fresh research.</h3><p>New briefs appear here after their sources and assumptions have been reviewed.</p><a href="index.html">Explore the collection</a></div>';
